import { SheetPanels } from '../../slots/defs/sheetPanels';
import { STATUSES, useClaims } from '../claims/useClaims';
import { showDue, totalDue } from '../rates/useRates';
import { crewDues, useCrews } from '../crews/useCrews';
import { useSheetTotals } from '../claims/useSheetTotals';
import { usePeople } from '../people/usePeople';
import { useWatches } from '../watch/useWatches';

/**
 * The sheet's header, shown at all times: how many people are on the sheet (retired ones
 * included), how many claims have each status (as the summary counts them), and the sheet's
 * due-total and overdue-total (as the totals work them out). And the signed-in user's own figures:
 * the due-total and overdue-total of the person whose name or an alias is the user's name (as names
 * are compared: case and the spaces around it ignored); blank when there is no such person. And the
 * user's crew total: the due-totals of the crews led by a person with the user's name, added up
 * (n/a ones skipped); blank when no such person leads a crew. And how many REVIEW claims are
 * assigned to the user for review. And the user's watched total: the due-totals of the people the
 * user watches, added up (n/a ones skipped); 0.00 when watching no one.
 */
function SheetHeader({ user, sheet }: { user: string; sheet: string }) {
  const { data: all = [] } = useClaims(sheet);
  const { data: everyone = [] } = usePeople(sheet);
  const { dueTotal, overdueTotal, perPerson } = useSheetTotals(sheet);
  const key = (n: string) => n.trim().toLowerCase();
  const { data: crews = [] } = useCrews(sheet);
  const isMine = (p: { name: string; aliases: string[] }) => [p.name, ...p.aliases].some((n) => key(n) === key(user));
  const me = perPerson.find(({ person }) => isMine(person));
  const myIds = new Set(perPerson.filter(({ person }) => isMine(person)).map(({ person }) => person.id));
  const ledCrews = crews.filter((c) => myIds.has(c.leadId));
  const { data: watched = [] } = useWatches(sheet, user);
  const watchedDues = perPerson.filter(({ person }) => watched.includes(person.id)).map(({ due }) => due);
  return (
    <header data-testid="sheet-header">
      <span>
        People: <strong data-testid="header-people-count">{everyone.length}</strong>
      </span>
      {STATUSES.map((s) => (
        <span key={s}>
          {' '}
          {s}: <strong data-testid={`header-claims-${s}-count`}>{all.filter((c) => c.status === s).length}</strong>
        </span>
      ))}
      <span>
        {' '}
        Due: <strong data-testid="header-due-total">{dueTotal}</strong>
      </span>
      <span>
        {' '}
        Overdue: <strong data-testid="header-overdue-total">{overdueTotal}</strong>
      </span>
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import type { Person } from '../people/usePeople';
import { downloadCsv, useSheetRead } from './csv';

/** The row's cells the export holds, in order. */
const CELLS = [
  'person-name',
  'person-grade',
  'person-claimed',
  'person-due-total',
  'person-statement-count',
  'person-overdue-total',
  'person-hold',
  'person-retired',
  'person-aliases',
  'person-score',
];

/**
 * A person's export: the button downloads their row as a CSV file, a header line `cell,value` then
 * one line per cell above, each with the value exactly as the row shows it (read from the row
 * itself, so it is the figure on screen; a cell the row does not show is blank). The button waits
 * for the sheet's reads, as the other exports do.
 */
function PersonExport({ sheet, person }: { user: string; sheet: string; person: Person }) {
  const read = useSheetRead(sheet);
  const exportRow = (button: HTMLElement) => {
    const row = button.closest('tr');
    const lines = [['cell', 'value']];
    for (const id of CELLS) {
      const cell = row?.querySelector(`:scope > [data-testid="${id}"]`);
      lines.push([id, cell?.textContent ?? '']);
    }
    downloadCsv(lines, `person-${sheet}-${person.id}.csv`);
  };
  return (
    <td>
      <button type="button" data-testid="person-export" disabled={!read} onClick={(e) => exportRow(e.currentTarget)}>
        Export row (CSV)
      </button>
    </td>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 90, Component: () => <th>Export</th> }),
  PersonCells.fill({ order: 90, Component: PersonExport }),
];

